struct Rectangle {
    width: u32,
    height: u32,
}

impl Rectangle {
    // 1. Constructor (Associated Function) - مفيهاش self
    pub fn new(width: u32, height: u32) -> Self {
        Self { width, height }
    }

    // 2. Method للاستعارة والقراءة فقط (&self)
    pub fn area(&self) -> u32 {
        self.width * self.height
    }

    // 3. Method للتعديل (&mut self)
    pub fn scale(&mut self, factor: u32) {
        self.width *= factor;
        self.height *= factor;
    }

    // 4. Method تستهلك الكائن وتنقل ملكيته (self)
    pub fn destroy(self) {
        println!("تم استهلاك المستطيل بحجم {}x{} وحذف موارده!", self.width, self.height);
    }
}

fn main() {
    let mut rect = Rectangle::new(30, 50);
    println!("المساحة الأصلية: {}", rect.area());

    rect.scale(2);
    println!("المساحة بعد التكبير: {}", rect.area());

    rect.destroy(); // الكائن مات هنا

    // rect.area(); // 💥 Error: borrow of moved value `rect`
}

fn handle_event(event: WebEvent) {
    match event {
        WebEvent::PageLoad => {
            println!("تم تحميل الصفحة بنجاح!");
        }
        WebEvent::KeyPress(c) => {
            println!("المستخدم ضغط على زر: '{}'", c);
        }
        WebEvent::Paste(text) => {
            println!("تم لصق نص طوله {} حرف: {}", text.len(), text);
        }
        WebEvent::Click { x, y } => {
            println!("تم النقر في الإحداثيات: X={}, Y={}", x, y);
        }
        WebEvent::ChangeColor(r, g, b) => {
            println!("تغيير اللون إلى RGB({}, {}, {})", r, g, b);
        }
    }
}

