// 1. تعريف الـ Trait
pub trait Summary {
    // دالة يجب على كل Struct كتابتها بنفسه:
    fn summarize_author(&self) -> String;

    // دالة لها Default Implementation تقدر كل Structs تستخدمها مباشرة:
    fn summarize(&self) -> String {
        format!("(اقرأ المزيد من الكاتب: {}...)", self.summarize_author())
    }
}

// 2. تطبيق الـ Trait على NewsArticle
pub struct NewsArticle {
    pub headline: String,
    pub location: String,
    pub author: String,
    pub content: String,
}

impl Summary for NewsArticle {
    fn summarize_author(&self) -> String {
        format!("الصحفي {}", self.author)
    }

    // عملنا Override للدالة الافتراضية:
    fn summarize(&self) -> String {
        format!("{}، بقلم {} ({})", self.headline, self.author, self.location)
    }
}

// 3. تطبيق الـ Trait على Tweet
pub struct Tweet {
    pub username: String,
    pub content: String,
    pub reply_count: u32,
}

impl Summary for Tweet {
    fn summarize_author(&self) -> String {
        format!("@{}", self.username)
    }
    // Tweet هتعتمد على الـ Default Implementation لدالة summarize()!
}

// دالة تقبل أي كائن يطبق Summary:
pub fn notify(item: &impl Summary) {
    println!("🔔 تنبيه عاجل: {}", item.summarize());
}

fn main() {
    let tweet = Tweet {
        username: String::from("tommy_coder"),
        content: String::from("Rust 2026 is mindblowing!"),
        reply_count: 14,
    };

    let article = NewsArticle {
        headline: String::from("Rust تكتسح عالم أنظمة التشغيل"),
        location: String::from("القاهرة"),
        author: String::from("أحمد إبراهيم"),
        content: String::from("تفاصيل الخبر..."),
    };

    notify(&tweet);   // 🔔 تنبيه عاجل: (اقرأ المزيد من الكاتب: @tommy_coder...)
    notify(&article); // 🔔 تنبيه عاجل: Rust تكتسح عالم أنظمة التشغيل، بقلم أحمد إبراهيم (القاهرة)
}

// دالة تقارن بين نصين وترجع الأطول:
fn longest<'a>(x: &'a str, y: &'a str) -> &'a str {
    if x.len() > y.len() {
        x
    } else {
        y
    }
}

